def populate_submission_assignments(apps, schema_editor):
    Submission = apps.get_model('core', 'Submission')
    database = schema_editor.connection.alias

    for submission in Submission.objects.using(database).select_related('group').iterator():
        if submission.group_id is None:
            raise RuntimeError(
                'Cannot preserve a submission without its legacy group assignment.'
            )
        Submission.objects.using(database).filter(pk=submission.pk).update(
            assignment_id=submission.group.assignment_id,
        )

    if Submission.objects.using(database).filter(assignment__isnull=True).exists():
        raise RuntimeError('Some submissions could not be linked to their assignments.')


